fn handle_open_font(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let Some(request) = x11::open_font_request(body) else {
        debug!(
            "client {} #{} OpenFont (parse failed)",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    };
    debug!(
        "client {} #{} OpenFont {:?}",
        client_id.0, sequence.0, request.name
    );
    let new_id = request.font.0;
    let validation_failed = {
        let handle = state.clients.get(&client_id.0).expect("client registered");
        !crate::server::IdAllocator::validate_owned(
            new_id,
            handle.resource_id_base,
            handle.resource_id_mask,
        ) || state.resources.any_resource_exists(request.font)
    };
    if validation_failed {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_ID_CHOICE,
            new_id,
            45,
        );
    }
    let host_result = match backend.open_font(origin, &request.name) {
        Ok(pair) => Some(pair),
        Err(err) => {
            log::warn!(
                "client {} OpenFont {:?} failed on host: {err}",
                client_id.0,
                request.name
            );
            None
        }
    };
    // Even when the host font open failed, install the font ID locally
    // so subsequent OpenFont calls on the same XID raise BadIDChoice
    // (X11 spec: BadIDChoice fires on duplicate IDs regardless of
    // whether the resource is actually backed). Use a sentinel host
    // handle that drawing paths will recognise as "no glyph data".
    let (host_handle, mut metrics) = host_result.unwrap_or_else(|| {
        (
            crate::backend::FontHandle::from_raw(0xffff_ffff).expect("nonzero sentinel"),
            x11::FontMetrics {
                min_bounds: x11::CharInfo::default(),
                max_bounds: x11::CharInfo::default(),
                min_char_or_byte2: 0,
                max_char_or_byte2: 0,
                default_char: 0,
                draw_direction: 0,
                min_byte1: 0,
                max_byte1: 0,
                all_chars_exist: false,
                font_ascent: 0,
                font_descent: 0,
                properties: Vec::new(),
                char_infos: Vec::new(),
            },
        )
    });
    {
        // Backends that don't proxy to a real X server (KMS) can't
        // populate font properties from upstream and return an empty
        // properties vec. Synthesize the standard XLFD-derived
        // properties (FOUNDRY, FAMILY_NAME, WEIGHT_NAME, ..., FONT)
        // so apps that interrogate them — fvwm3 menu rendering,
        // Xt/Athena widgets — don't silently skip text drawing.
        if metrics.properties.is_empty() {
            metrics.properties = synthesize_font_properties(&mut state.atoms, &request.name);
            log::debug!(
                "OpenFont {:?}: synthesized {} property bytes ({} props), {} char_infos",
                request.name,
                metrics.properties.len(),
                metrics.properties.len() / 8,
                metrics.char_infos.len(),
            );
        }
        state
            .resources
            .install_font(client_id, request.font, request.name, host_handle, metrics);
    }
    Ok(RequestOutcome::Handled)
}

/// Build a `FontProp` byte sequence (8 bytes per property: name atom +
/// CARD32 value) from an XLFD font name. String-typed properties get
/// their value interned as an atom; integer-typed properties carry
/// the int directly per the XLFD spec.
///
/// XLFD components:
/// `-foundry-family-weight-slant-setwidth-addstyle-pixelsize-pointsize-resx-resy-spacing-avgwidth-charset-encoding`
fn synthesize_font_properties(atoms: &mut crate::server::AtomTable, xlfd: &str) -> Vec<u8> {
    let parts: Vec<&str> = xlfd.split('-').collect();
    // Real XLFDs start with '-' so split yields an empty first element.
    // Names that aren't proper XLFDs (e.g. "fixed", "cursor") get only a
    // FONT property pointing at the literal string — better than empty.
    let mut out: Vec<u8> = Vec::with_capacity(15 * 8);

    let put_string =
        |atoms: &mut crate::server::AtomTable, out: &mut Vec<u8>, name: &str, value: &str| {
            let name_atom = atoms.intern(name, false).0;
            let value_atom = atoms.intern(value, false).0;
            out.extend_from_slice(&name_atom.to_le_bytes());
            out.extend_from_slice(&value_atom.to_le_bytes());
        };
    let put_int =
        |atoms: &mut crate::server::AtomTable, out: &mut Vec<u8>, name: &str, value: i32| {
            let name_atom = atoms.intern(name, false).0;
            out.extend_from_slice(&name_atom.to_le_bytes());
            out.extend_from_slice(&(value as u32).to_le_bytes());
        };

    // FONT property always: the full XLFD as an atom value.
    put_string(atoms, &mut out, "FONT", xlfd);

    // XLFD-shaped name: -foundry-family-weight-slant-setwidth-addstyle-pixel-point-resx-resy-spacing-avgwidth-charset-encoding
    // parts[0] is the empty leading "" before the first '-'.
    if parts.len() >= 15 {
        put_string(atoms, &mut out, "FOUNDRY", parts[1]);
        put_string(atoms, &mut out, "FAMILY_NAME", parts[2]);
        put_string(atoms, &mut out, "WEIGHT_NAME", parts[3]);
        put_string(atoms, &mut out, "SLANT", parts[4]);
        put_string(atoms, &mut out, "SETWIDTH_NAME", parts[5]);
        put_string(atoms, &mut out, "ADD_STYLE_NAME", parts[6]);
        if let Ok(v) = parts[7].parse::<i32>() {
            put_int(atoms, &mut out, "PIXEL_SIZE", v);
        }
        if let Ok(v) = parts[8].parse::<i32>() {
            put_int(atoms, &mut out, "POINT_SIZE", v);
        }
        if let Ok(v) = parts[9].parse::<i32>() {
            put_int(atoms, &mut out, "RESOLUTION_X", v);
        }
        if let Ok(v) = parts[10].parse::<i32>() {
            put_int(atoms, &mut out, "RESOLUTION_Y", v);
        }
        put_string(atoms, &mut out, "SPACING", parts[11]);
        if let Ok(v) = parts[12].parse::<i32>() {
            put_int(atoms, &mut out, "AVERAGE_WIDTH", v);
        }
        put_string(atoms, &mut out, "CHARSET_REGISTRY", parts[13]);
        put_string(atoms, &mut out, "CHARSET_ENCODING", parts[14]);
    }
    out
}

fn handle_close_font(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some(font) = x11::free_resource_id(body) {
        let removed = state.resources.close_font(font);
        if let Some(removed) = removed {
            let _ = backend.close_font(origin, removed.host_xid.as_raw());
        }
    }
    debug!("client {} #{} CloseFont", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_set_selection_owner(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() < 8 {
        debug!(
            "client {} #{} SetSelectionOwner (short body)",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    }
    let window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
    let selection = AtomId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
    let time_val = if body.len() >= 12 {
        u32::from_le_bytes([body[8], body[9], body[10], body[11]])
    } else {
        0u32
    };

    let old = selection_owner_target_id(state, selection);
    let old_window = state.selections.get(&selection).copied();
    if window.0 == 0 {
        state.selections.remove(&selection);
    } else {
        state.selections.insert(selection, window);
    }
    let send_clear =
        old_window.is_some() && old_window != (if window.0 == 0 { None } else { Some(window) });
    let name = state.atoms.name(selection).map(str::to_owned);
    debug!(
        "client {} #{} SetSelectionOwner {} -> 0x{:x}",
        client_id.0,
        sequence.0,
        name.as_deref().unwrap_or("?"),
        window.0
    );

    if send_clear && let Some((old_window, old_target)) = old {
        let _dropped = fanout_event_to_clients(state, &[old_target], |buf, seq, order| {
            x11::encode_selection_clear_event(buf, seq, order, time_val, old_window, selection);
        });
    }
    Ok(RequestOutcome::Handled)
}

fn handle_convert_selection(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() < 20 {
        return Ok(RequestOutcome::Handled);
    }
    let requestor = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
    let selection = AtomId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
    let target_atom = AtomId(u32::from_le_bytes([body[8], body[9], body[10], body[11]]));
    let property = AtomId(u32::from_le_bytes([body[12], body[13], body[14], body[15]]));
    let time_val = u32::from_le_bytes([body[16], body[17], body[18], body[19]]);

    if let Some((owner_window, owner_id)) = selection_owner_target_id(state, selection) {
        let _dropped = fanout_event_to_clients(state, &[owner_id], |buf, seq, order| {
            x11::encode_selection_request_event(
                buf,
                seq,
                order,
                time_val,
                owner_window,
                requestor,
                selection,
                target_atom,
                property,
            );
        });
        debug!(
            "client {} #{} ConvertSelection -> owner 0x{:x}",
            client_id.0, sequence.0, owner_window.0
        );
    } else {
        // No owner — send SelectionNotify(None) to the requestor.
        let requestor_id = state
            .resources
            .window_owner(requestor)
            .and_then(|cid| client_target_id(state, cid));
        if let Some(rt) = requestor_id {
            let mut template = [0u8; 32];
            template[0] = 31; // SelectionNotify
            template[4..8].copy_from_slice(&time_val.to_le_bytes());
            template[8..12].copy_from_slice(&requestor.0.to_le_bytes());
            template[12..16].copy_from_slice(&selection.0.to_le_bytes());
            template[16..20].copy_from_slice(&target_atom.0.to_le_bytes());
            // property = 0 (None): conversion failed.
            let _dropped = fanout_raw_event_to_clients(
                state,
                &[rt],
                &template,
                yserver_protocol::x11::ClientByteOrder::LittleEndian,
            );
        }
        debug!(
            "client {} #{} ConvertSelection: no owner, sent SelectionNotify(None)",
            client_id.0, sequence.0
        );
    }
    Ok(RequestOutcome::Handled)
}

fn handle_send_event(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    use yserver_protocol::x11::ClientByteOrder;
    // The 32-byte event template inside SendEvent is in the *sender's*
    // byte order. Note: the request body's typed prefix (destination +
    // event_mask) was already swapped to LE by request_swap; only the
    // template itself stays in the sender's byte order so we can
    // re-encode per recipient.
    let sender_byte_order = state
        .clients
        .get(&client_id.0)
        .map_or(ClientByteOrder::LittleEndian, |c| c.byte_order);
    let Some(req) = x11::send_event_request(header.data, body) else {
        debug!(
            "client {} #{} SendEvent (parse failed)",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    };
    // Set the sent-event bit (bit 7 of first byte).
    let mut event_copy = *req.event;
    event_copy[0] |= 0x80;

    let mut targets: Vec<ClientId> = if req.destination.0 == 0xffff_ffff {
        subscribers_by_id(state, ROOT_WINDOW, req.event_mask)
    } else if req.event_mask == 0 {
        state
            .resources
            .window_owner(req.destination)
            .and_then(|owner| client_target_id(state, owner))
            .into_iter()
            .collect()
    } else {
        let mut current = req.destination;
        loop {
            let t = subscribers_by_id(state, current, req.event_mask);
            if !t.is_empty() || !req.propagate {
                break t;
            }
            let Some(parent) = state.resources.parent_of(current) else {
                break Vec::new();
            };
            if parent == current {
                break Vec::new();
            }
            current = parent;
        }
    };
    // GDK3 has a NULL-device crash in `proxy_button_event` when its
    // XI2 wrapper's `get_client_pointer()` returns NULL for a
    // synthetic core ButtonPress/Release/Motion/Enter/Leave: the
    // ensuing `_gdk_display_get_pointer_info(display, NULL)` returns
    // NULL and the next line dereferences it. The crash fires on the
    // master-pointer alias even when XIQueryDevice and
    // XIGetClientPointer both report device 2 — somewhere the
    // id_table lookup miscarries. Mate-panel hits it on every
    // workspace-switch click because wnck-applet SendEvents a
    // synthetic ButtonRelease into the panel.
    //
    // For event types that have XI2 counterparts (4–8 = Button*,
    // Motion, Enter, Leave), drop any target client that has an XI2
    // selection covering the destination (or any ancestor) for the
    // matching XI2 type bit. The XI2 bit index equals the core type
    // for these five events. Core-only clients (fvwm, wmaker, e16,
    // legacy X apps) still receive the event unchanged.
    let core_type = req.event[0] & 0x7f;
    if matches!(core_type, 4..=8) {
        let xi2_bit = 1u32 << core_type;
        let before = targets.len();
        targets.retain(|target| {
            let Some(target_client) = state.clients.get(&target.0) else {
                return true;
            };
            let mut current = req.destination;
            loop {
                for deviceid in [0u16, 1, 2, 3] {
                    if let Some(m) = target_client.xi2_masks.get(&(current, deviceid))
                        && (m & xi2_bit) != 0
                    {
                        return false;
                    }
                }
                let Some(parent) = state.resources.parent_of(current) else {
                    return true;
                };
                if parent == current {
                    return true;
                }
                current = parent;
            }
        });
        if targets.len() != before {
            debug!(
                "client {} #{} SendEvent core type={} dest=0x{:x} dropped \
                 {} target(s) with overlapping XI2 selection (GDK3 NULL-device guard)",
                client_id.0,
                sequence.0,
                core_type,
                req.destination.0,
                before - targets.len(),
            );
        }
    }
    let _dropped = fanout_raw_event_to_clients(state, &targets, &event_copy, sender_byte_order);
    let core_type_logged = req.event[0] & 0x7f;
    // For synthetic ConfigureNotify (type=22), decode and log x/y/w/h
    // so we can see what the WM tells clients about their root
    // position. The wire body (after the 4-byte type/seq prefix) is:
    //   event_window(4) + window(4) + above_sibling(4) +
    //   x(2) + y(2) + width(2) + height(2) + border(2) +
    //   override_redirect(1) + pad(1)
    if core_type_logged == 22 {
        let e = &req.event;
        let event_w = u32::from_le_bytes([e[4], e[5], e[6], e[7]]);
        let window_w = u32::from_le_bytes([e[8], e[9], e[10], e[11]]);
        let above = u32::from_le_bytes([e[12], e[13], e[14], e[15]]);
        let x = i16::from_le_bytes([e[16], e[17]]);
        let y = i16::from_le_bytes([e[18], e[19]]);
        let w = u16::from_le_bytes([e[20], e[21]]);
        let h = u16::from_le_bytes([e[22], e[23]]);
        let bw = u16::from_le_bytes([e[24], e[25]]);
        let or = e[26];
        debug!(
            "client {} #{} SendEvent type=22 (ConfigureNotify) dest=0x{:x} \
             ev_win=0x{:x} win=0x{:x} above=0x{:x} pos=({},{}) size=({}x{}) \
             border={} override={} targets={:?}",
            client_id.0,
            sequence.0,
            req.destination.0,
            event_w,
            window_w,
            above,
            x,
            y,
            w,
            h,
            bw,
            or,
            targets.iter().map(|c| c.0).collect::<Vec<_>>(),
        );
    } else {
        debug!(
            "client {} #{} SendEvent type={} dest=0x{:x} event_mask=0x{:x} propagate={} targets={:?}",
            client_id.0,
            sequence.0,
            core_type_logged,
            req.destination.0,
            req.event_mask,
            req.propagate,
            targets.iter().map(|c| c.0).collect::<Vec<_>>(),
        );
    }
    Ok(RequestOutcome::Handled)
}

fn handle_get_atom_name(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let atom = x11::request_atom(body);
    debug!(
        "client {} #{} GetAtomName {}",
        client_id.0, sequence.0, atom.0
    );
    let local = state.atoms.name(atom).map(str::to_owned);
    let name = match local {
        Some(n) => Some(n),
        None => backend.get_atom_name(origin, atom.0).ok().flatten(),
    };
    match name {
        Some(name) => {
            let Some(client) = state.clients.get_mut(&client_id.0) else {
                return Ok(RequestOutcome::Handled);
            };
            let byte_order = client.byte_order;
            let mut buf: Vec<u8> = Vec::with_capacity(32 + name.len());
            x11::write_get_atom_name_reply(&mut buf, byte_order, sequence, &name)?;
            Ok(write_to_client(client, client_id, &buf))
        }
        None => emit_x11_error(state, client_id, sequence, x11::error::BAD_ATOM, atom.0, 17),
    }
}

fn handle_query_pointer(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let queried_window = if body.len() >= 4 {
        ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]))
    } else {
        ROOT_WINDOW
    };
    let pointer = backend.query_pointer(origin).ok().filter(|p| p.same_screen);
    let reply_data = if let Some(pointer) = pointer {
        // The KMS backend's PointerPosition carries cursor coordinates
        // in root-absolute screen space (win_x/win_y are misnamed
        // historical fields). Compute win-relative by subtracting the
        // queried window's absolute origin. Without this xeyes (and
        // any other client doing per-window pointer queries) sees
        // win_x/win_y unchanged after the WM moves the window, so
        // the iris locks to a fixed offset and stops tracking.
        let (origin_x, origin_y) = state.resources.window_absolute_position(queried_window);
        let root_x = pointer.win_x;
        let root_y = pointer.win_y;
        let win_x = i16::try_from(i32::from(root_x).saturating_sub(origin_x)).unwrap_or(i16::MAX);
        let win_y = i16::try_from(i32::from(root_y).saturating_sub(origin_y)).unwrap_or(i16::MAX);
        // Per X11 spec, `child` is the direct child of `queried_window`
        // that contains the pointer, or None (0) if the pointer is on
        // the queried window itself or on no descendant. Previously
        // this was hardcoded to ROOT_WINDOW, which made GTK's
        // QueryPointer-based hover/tooltip polling never see a
        // transition between children — xfce4-panel spun 3500 times
        // per second on QueryPointer, starving its event loop and
        // dropping clicks on every panel applet.
        let child = state
            .resources
            .direct_child_at(queried_window, win_x, win_y)
            .unwrap_or(ResourceId(0));
        x11::QueryPointerReply {
            root: ROOT_WINDOW,
            child,
            root_x,
            root_y,
            win_x,
            win_y,
            mask: pointer.mask,
        }
    } else {
        x11::QueryPointerReply {
            root: ROOT_WINDOW,
            child: ResourceId(0),
            ..Default::default()
        }
    };
    debug!(
        "client {} #{} QueryPointer queried=0x{:x} -> root=({},{}) win=({},{}) child=0x{:x} mask=0x{:x}",
        client_id.0,
        sequence.0,
        queried_window.0,
        reply_data.root_x,
        reply_data.root_y,
        reply_data.win_x,
        reply_data.win_y,
        reply_data.child.0,
        reply_data.mask,
    );
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_query_pointer_reply(&mut buf, byte_order, sequence, reply_data)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_warp_pointer(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 20 {
        let dst_window = ResourceId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
        let dst_x = i16::from_le_bytes([body[16], body[17]]);
        let dst_y = i16::from_le_bytes([body[18], body[19]]);
        let host_target = if dst_window.0 == 0 {
            None
        } else {
            state
                .resources
                .host_drawable_target(dst_window)
                .map(|t| (t.host_xid(), dst_x, dst_y))
        };
        if let Some((host_xid, x, y)) = host_target {
            let _ = backend.warp_pointer(origin, host_xid, x, y);
        }
    }
    debug!("client {} #{} WarpPointer", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_get_modifier_mapping(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
) -> io::Result<RequestOutcome> {
    debug!("client {} #{} GetModifierMapping", client_id.0, sequence.0);
    let proxied = backend.get_modifier_mapping(origin).ok();
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(64);
    if let Some((kpm, keys)) = proxied {
        x11::write_get_modifier_mapping_reply_with_keycodes(
            &mut buf, byte_order, sequence, kpm, &keys,
        )?;
    } else {
        x11::write_get_modifier_mapping_reply(&mut buf, byte_order, sequence)?;
    }
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_change_property(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let Some(req) = x11::change_property_request(header.data, body) else {
        // Diagnostic: dump the request header + body shape that we
        // rejected as malformed, so we can see what the client sent.
        let preview_len = body.len().min(64);
        let body_preview = &body[..preview_len];
        debug!(
            "ChangeProperty BadLength (parse-fail): client={} seq={} \
             header.data={:#x} body.len={} length_units={} preview={:02x?}",
            client_id.0,
            sequence.0,
            header.data,
            body.len(),
            header.length_units,
            body_preview,
        );
        return emit_x11_error(state, client_id, sequence, x11::error::BAD_LENGTH, 0, 18);
    };
    let Some(mode) = properties::ChangeMode::from_protocol(req.mode) else {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_VALUE,
            u32::from(req.mode),
            18,
        );
    };
    let Some(format) = properties::PropertyFormat::from_protocol(req.format) else {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_VALUE,
            u32::from(req.format),
            18,
        );
    };
    let expected_bytes = (req.length as usize).checked_mul(format.bytes());
    if expected_bytes != Some(req.data.len()) {
        debug!(
            "ChangeProperty BadLength (length mismatch): client={} seq={} \
             req.length={} format={} expected={:?} got={}",
            client_id.0,
            sequence.0,
            req.length,
            req.format,
            expected_bytes,
            req.data.len(),
        );
        return emit_x11_error(state, client_id, sequence, x11::error::BAD_LENGTH, 0, 18);
    }
    if state.resources.window(req.window).is_none() {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            req.window.0,
            18,
        );
    }
    if !state.atoms.exists(req.property) {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_ATOM,
            req.property.0,
            18,
        );
    }
    if !state.atoms.exists(req.r#type) {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_ATOM,
            req.r#type.0,
            18,
        );
    }
    // Diagnostic: log WM_CLASS (and _NET_WM_PID) so we can map
    // yserver client_id → user-space process when debugging
    // missing-click / dead-applet issues. WM_CLASS is two
    // null-terminated strings (instance, class); _NET_WM_PID is a
    // CARD32. Both are set once near client init, so noise is
    // bounded.
    if let Some(prop_name) = state.atoms.name(req.property) {
        if prop_name == "WM_CLASS" && req.format == 8 {
            let s = String::from_utf8_lossy(&req.data).replace('\0', " | ");
            log::info!(
                "client {} WM_CLASS on 0x{:x}: {}",
                client_id.0,
                req.window.0,
                s.trim_end_matches(" | "),
            );
        } else if prop_name == "_NET_WM_PID" && req.format == 32 && req.data.len() >= 4 {
            let pid = u32::from_le_bytes([req.data[0], req.data[1], req.data[2], req.data[3]]);
            log::info!(
                "client {} _NET_WM_PID on 0x{:x}: {}",
                client_id.0,
                req.window.0,
                pid,
            );
        } else if prop_name == "_NET_FRAME_EXTENTS" && req.format == 32 && req.data.len() >= 16 {
            // 4× CARDINAL: left, right, top, bottom (frame inset
            // around the client window). GTK reads this to position
            // popups; if it's corrupted we'd see the popup-placement
            // bug for reparented application windows.
            let l = u32::from_le_bytes([req.data[0], req.data[1], req.data[2], req.data[3]]);
            let r = u32::from_le_bytes([req.data[4], req.data[5], req.data[6], req.data[7]]);
            let t = u32::from_le_bytes([req.data[8], req.data[9], req.data[10], req.data[11]]);
            let b = u32::from_le_bytes([req.data[12], req.data[13], req.data[14], req.data[15]]);
            log::info!(
                "client {} _NET_FRAME_EXTENTS on 0x{:x}: left={} right={} top={} bottom={}",
                client_id.0,
                req.window.0,
                l,
                r,
                t,
                b,
            );
        } else if prop_name == "_NET_WORKAREA" && req.format == 32 && req.data.len() >= 16 {
            // 4× CARDINAL per desktop: x, y, width, height. Log
            // the first desktop's quad; subsequent desktops are
            // rare and the first is the one popup placement uses.
            let x = u32::from_le_bytes([req.data[0], req.data[1], req.data[2], req.data[3]]);
            let y = u32::from_le_bytes([req.data[4], req.data[5], req.data[6], req.data[7]]);
            let w = u32::from_le_bytes([req.data[8], req.data[9], req.data[10], req.data[11]]);
            let h = u32::from_le_bytes([req.data[12], req.data[13], req.data[14], req.data[15]]);
            log::info!(
                "client {} _NET_WORKAREA on 0x{:x}: x={} y={} w={} h={} (desktop 0)",
                client_id.0,
                req.window.0,
                x,
                y,
                w,
                h,
            );
        }
    }
    let existing = state
        .resources
        .window_property(req.window, req.property)
        .cloned();
    let new_value =
        match properties::apply_change(existing.as_ref(), mode, req.r#type, format, &req.data) {
            Ok(v) => v,
            Err(properties::ChangePropertyError::BadMatch) => {
                return emit_x11_error(
                    state,
                    client_id,
                    sequence,
                    x11::error::BAD_MATCH,
                    req.window.0,
                    18,
                );
            }
            Err(properties::ChangePropertyError::BadAlloc) => {
                return emit_x11_error(state, client_id, sequence, x11::error::BAD_ALLOC, 0, 18);
            }
            Err(properties::ChangePropertyError::BadValue) => {
                return emit_x11_error(state, client_id, sequence, x11::error::BAD_VALUE, 0, 18);
            }
        };
    state
        .resources
        .set_window_property(req.window, req.property, new_value);
    let timestamp = state.timestamp_now();
    let window = req.window;
    let property = req.property;
    let _dropped = emit_window_event_to_state(
        state,
        window,
        0x0040_0000, // PropertyChangeMask
        |buf, seq, order| {
            x11::encode_property_notify_event(buf, seq, order, window, property, timestamp, false);
        },
    );
    debug!("client {} #{} ChangeProperty", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_get_property(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    use yserver_protocol::x11::ClientByteOrder;
    let byte_order = state
        .clients
        .get(&client_id.0)
        .map_or(ClientByteOrder::LittleEndian, |c| c.byte_order);
    let Some(req) = x11::get_property_request(header.data, body) else {
        return emit_x11_error(state, client_id, sequence, x11::error::BAD_LENGTH, 0, 20);
    };
    if state.resources.window(req.window).is_none() {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            req.window.0,
            20,
        );
    }
    if !state.atoms.exists(req.property) {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_ATOM,
            req.property.0,
            20,
        );
    }
    if req.r#type.0 != 0 && !state.atoms.exists(req.r#type) {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_ATOM,
            req.r#type.0,
            20,
        );
    }
    // Build the reply against an immutable borrow of state.resources,
    // copy the bytes into an owned buffer, then drop the borrow before
    // we touch state again for the optional delete + fanout.
    let (reply_bytes, type_matched, slice_bytes_after, existing_some) = {
        let existing = state
            .resources
            .window_property(req.window, req.property)
            .cloned();
        let slice = match properties::slice_for_get(
            existing.as_ref(),
            req.r#type,
            req.long_offset,
            req.long_length,
        ) {
            Ok(s) => s,
            Err(properties::ChangePropertyError::BadValue) => {
                return emit_x11_error(
                    state,
                    client_id,
                    sequence,
                    x11::error::BAD_VALUE,
                    req.long_offset,
                    20,
                );
            }
            Err(_) => unreachable!("slice_for_get only returns BadValue on error"),
        };
        let value_len_units = if slice.format == 0 {
            0
        } else {
            slice.value.len() as u32 / u32::from(slice.format / 8)
        };
        let mut buf: Vec<u8> = Vec::with_capacity(32 + slice.value.len());
        x11::write_get_property_reply(
            &mut buf,
            byte_order,
            sequence,
            x11::GetPropertyReply {
                format: slice.format,
                r#type: slice.r#type,
                bytes_after: slice.bytes_after,
                value_len: value_len_units,
                value: slice.value,
            },
        )?;
        let type_matched = existing
            .as_ref()
            .is_some_and(|p| req.r#type.0 == 0 || req.r#type == p.r#type);
        (buf, type_matched, slice.bytes_after, existing.is_some())
    };
    // Send reply bytes through client_io::write_or_buffer.
    let outcome = match state.clients.get_mut(&client_id.0) {
        Some(client) => write_to_client(client, client_id, &reply_bytes),
        None => RequestOutcome::Handled,
    };
    if matches!(outcome, RequestOutcome::Disconnect(_)) {
        return Ok(outcome);
    }
    // Optional delete + PropertyNotify fanout (state=true) when
    // delete=1 fires per spec.
    if req.delete && type_matched && slice_bytes_after == 0 && existing_some {
        let _ = state
            .resources
            .delete_window_property(req.window, req.property);
        let timestamp = state.timestamp_now();
        let window = req.window;
        let property = req.property;
        let _dropped = emit_window_event_to_state(state, window, 0x0040_0000, |buf, seq, order| {
            x11::encode_property_notify_event(buf, seq, order, window, property, timestamp, true);
        });
    }
    debug!("client {} #{} GetProperty", client_id.0, sequence.0);
    Ok(outcome)
}

fn handle_delete_property(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let Some(req) = x11::delete_property_request(body) else {
        return emit_x11_error(state, client_id, sequence, x11::error::BAD_LENGTH, 0, 19);
    };
    if state.resources.window(req.window).is_none() {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            req.window.0,
            19,
        );
    }
    let removed = state
        .resources
        .delete_window_property(req.window, req.property);
    if removed.is_some() {
        let timestamp = state.timestamp_now();
        let window = req.window;
        let property = req.property;
        let _dropped = emit_window_event_to_state(state, window, 0x0040_0000, |buf, seq, order| {
            x11::encode_property_notify_event(buf, seq, order, window, property, timestamp, true);
        });
    }
    debug!("client {} #{} DeleteProperty", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_query_font(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    debug!("client {} #{} QueryFont", client_id.0, sequence.0);
    let metrics = x11::drawable_request_id(body)
        .and_then(|id| state.resources.fontable(id))
        .map(|font| font.metrics.clone())
        .unwrap_or_default();
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(64);
    x11::write_query_font_reply(&mut buf, byte_order, sequence, &metrics)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_query_text_extents(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    debug!("client {} #{} QueryTextExtents", client_id.0, sequence.0);
    let extents = x11::query_text_extents_request(header.data, body)
        .and_then(|req| {
            state
                .resources
                .fontable(req.fontable)
                .map(|font| font.metrics.text_extents(&req.chars))
        })
        .unwrap_or_default();
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_query_text_extents_reply(&mut buf, byte_order, sequence, extents)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_query_best_size(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let width = if body.len() >= 8 {
        u16::from_le_bytes([body[4], body[5]])
    } else {
        0
    };
    let height = if body.len() >= 8 {
        u16::from_le_bytes([body[6], body[7]])
    } else {
        0
    };
    debug!("client {} #{} QueryBestSize", client_id.0, sequence.0);
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_query_best_size_reply(&mut buf, byte_order, sequence, width, height)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_grab_pointer(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 20 {
        let grab_window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        let event_mask = u16::from_le_bytes([body[4], body[5]]);
        let cursor = ResourceId(u32::from_le_bytes([body[12], body[13], body[14], body[15]]));
        let time = u32::from_le_bytes([body[16], body[17], body[18], body[19]]);
        state.pointer_grab = Some((client_id, grab_window));
        state.pointer_grab_is_passive = false;
        state.active_pointer_grab = Some(crate::server::ActivePointerGrab {
            owner: client_id,
            grab_window,
            event_mask,
            cursor,
            time,
        });
    }
    debug!("client {} #{} GrabPointer", client_id.0, sequence.0);
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_grab_reply(&mut buf, byte_order, sequence, 0)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_ungrab_pointer(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
) -> io::Result<RequestOutcome> {
    state.pointer_grab = None;
    state.pointer_grab_is_passive = false;
    state.active_pointer_grab = None;
    state.frozen_pointer_event = None;
    debug!("client {} #{} UngrabPointer", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_grab_button(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 20 {
        let button = body[16];
        let grab_window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        let event_mask = u32::from(u16::from_le_bytes([body[4], body[5]]));
        let pointer_mode = body[6];
        let modifiers = u16::from_le_bytes([body[18], body[19]]);
        state.button_grabs.retain(|g| {
            !(g.owner == client_id
                && g.grab_window == grab_window
                && g.button == button
                && g.modifiers == modifiers)
        });
        state.button_grabs.push(crate::server::PassiveButtonGrab {
            owner: client_id,
            grab_window,
            button,
            modifiers,
            event_mask,
            pointer_mode,
        });
        debug!(
            "client {} GrabButton window=0x{:x} button={} modifiers=0x{:x}",
            client_id.0, grab_window.0, button, modifiers
        );
    }
    debug!("client {} #{} GrabButton", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_ungrab_button(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 6 {
        let button = header.data;
        let grab_window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        let modifiers = u16::from_le_bytes([body[4], body[5]]);
        state.button_grabs.retain(|g| {
            !(g.owner == client_id
                && g.grab_window == grab_window
                && (g.button == button || button == 0)
                && (g.modifiers == modifiers || modifiers == 0x8000))
        });
        debug!(
            "client {} UngrabButton window=0x{:x} button={} modifiers=0x{:x}",
            client_id.0, grab_window.0, button, modifiers
        );
    }
    debug!("client {} #{} UngrabButton", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_change_active_pointer_grab(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 12 {
        let cursor = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        let time = u32::from_le_bytes([body[4], body[5], body[6], body[7]]);
        let event_mask = u16::from_le_bytes([body[8], body[9]]);
        if let Some(g) = state.active_pointer_grab.as_mut()
            && g.owner == client_id
        {
            g.event_mask = event_mask;
            g.cursor = cursor;
            g.time = time;
        }
    }
    debug!(
        "client {} #{} ChangeActivePointerGrab",
        client_id.0, sequence.0
    );
    Ok(RequestOutcome::Handled)
}

fn handle_grab_keyboard(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 12 {
        let grab_window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        state.active_keyboard_grab = Some(crate::server::ActiveKeyboardGrab {
            owner: client_id,
            grab_window,
            source: crate::server::ActiveKeyboardGrabSource::Explicit,
        });
    }
    debug!("client {} #{} GrabKeyboard", client_id.0, sequence.0);
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_grab_reply(&mut buf, byte_order, sequence, 0)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_ungrab_keyboard(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
) -> io::Result<RequestOutcome> {
    if let Some(g) = state.active_keyboard_grab
        && g.owner == client_id
    {
        state.active_keyboard_grab = None;
    }
    debug!("client {} #{} UngrabKeyboard", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_grab_key(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some(req) = x11::parse_grab_key(body, header.data != 0) {
        let grab_window = ResourceId(req.grab_window);
        state.key_grabs.retain(|g| {
            !(g.owner == client_id
                && g.grab_window == grab_window
                && g.keycode == req.keycode
                && g.modifiers == req.modifiers)
        });
        state.key_grabs.push(crate::server::KeyGrab {
            owner: client_id,
            grab_window,
            keycode: req.keycode,
            modifiers: req.modifiers,
            owner_events: req.owner_events,
            pointer_mode: req.pointer_mode,
            keyboard_mode: req.keyboard_mode,
        });
        debug!(
            "client {} GrabKey window=0x{:x} keycode={} modifiers=0x{:x}",
            client_id.0, req.grab_window, req.keycode, req.modifiers
        );
    }
    debug!("client {} #{} GrabKey", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_ungrab_key(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some(req) = x11::parse_ungrab_key(body, header.data) {
        let grab_window = ResourceId(req.grab_window);
        state.key_grabs.retain(|g| {
            !(g.owner == client_id
                && g.grab_window == grab_window
                && (g.keycode == req.keycode || req.keycode == 0)
                && (g.modifiers == req.modifiers || req.modifiers == 0x8000))
        });
    }
    debug!("client {} #{} UngrabKey", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_get_selection_owner(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let owner = if body.len() >= 4 {
        let selection = AtomId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        state
            .selections
            .get(&selection)
            .copied()
            .unwrap_or(ResourceId(0))
    } else {
        ResourceId(0)
    };
    debug!(
        "client {} #{} GetSelectionOwner -> 0x{:x}",
        client_id.0, sequence.0, owner.0
    );
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_get_selection_owner_reply(&mut buf, byte_order, sequence, owner)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn window_geometry(window: &Window) -> x11::Geometry {
    x11::Geometry {
        root: ROOT_WINDOW,
        x: window.x,
        y: window.y,
        width: window.width,
        height: window.height,
        border_width: window.border_width,
        depth: window.depth,
    }
}

fn pixmap_geometry(pixmap: &Pixmap) -> x11::Geometry {
    x11::Geometry {
        root: ROOT_WINDOW,
        x: 0,
        y: 0,
        width: pixmap.width,
        height: pixmap.height,
        border_width: 0,
        depth: pixmap.depth,
    }
}

#[allow(clippy::cast_possible_truncation)]
fn handle_translate_coordinates(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let (child, dst_x, dst_y, log_src, log_dst, log_src_xy) = if body.len() >= 12 {
        let src_window = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        let dst_window = ResourceId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
        let src_x = i16::from_le_bytes([body[8], body[9]]);
        let src_y = i16::from_le_bytes([body[10], body[11]]);
        let (src_abs_x, src_abs_y) = state.resources.window_absolute_position(src_window);
        let abs_x = src_abs_x + i32::from(src_x);
        let abs_y = src_abs_y + i32::from(src_y);
        let (dst_abs_x, dst_abs_y) = state.resources.window_absolute_position(dst_window);
        let dst_x = (abs_x - dst_abs_x) as i16;
        let dst_y = (abs_y - dst_abs_y) as i16;
        let child = state
            .resources
            .child_containing_point(dst_window, abs_x, abs_y)
            .unwrap_or(ResourceId(0));
        (
            child,
            dst_x,
            dst_y,
            src_window.0,
            dst_window.0,
            (src_x, src_y),
        )
    } else {
        (ResourceId(0), 0i16, 0i16, 0u32, 0u32, (0i16, 0i16))
    };
    debug!(
        "client {} #{} TranslateCoordinates src=0x{:x} dst=0x{:x} src_xy=({},{}) -> dst_xy=({},{}) child=0x{:x}",
        client_id.0,
        sequence.0,
        log_src,
        log_dst,
        log_src_xy.0,
        log_src_xy.1,
        dst_x,
        dst_y,
        child.0,
    );
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_translate_coordinates_reply(&mut buf, byte_order, sequence, child, dst_x, dst_y)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn write_to_client(
    client: &mut crate::server::ClientState,
    client_id: ClientId,
    bytes: &[u8],
) -> RequestOutcome {
    match client_io::write_or_buffer(client, bytes) {
        Ok(WriteOutcome::Done | WriteOutcome::WouldBlock) => RequestOutcome::Handled,
        Ok(WriteOutcome::Disconnect) => RequestOutcome::Disconnect(client_id),
        Err(_) => RequestOutcome::Disconnect(client_id),
    }
}

#[cfg(test)]
mod tests {
    use std::{
        collections::{HashMap, HashSet, VecDeque},
        io::Read,
        os::unix::net::UnixStream,
        sync::{Arc, Mutex, atomic::AtomicU16},
    };

    use yserver_protocol::x11::{ClientByteOrder, ClientId, RequestHeader, SequenceNumber};

    use super::*;
    use yserver_protocol::x11::CreateWindowRequest;

    use crate::{
        backend::recording::{RecordedCall, RecordingBackend},
        resources::ROOT_WINDOW,
        server::{ClientState, ServerState},
    };

    fn install_client(state: &mut ServerState, id: u32) -> UnixStream {
        let (a, b) = UnixStream::pair().unwrap();
        state.clients.insert(
            id,
            ClientState {
                writer: Arc::new(Mutex::new(a)),
                byte_order: ClientByteOrder::LittleEndian,
                last_sequence: Arc::new(AtomicU16::new(0)),
                resource_id_base: 0,
                resource_id_mask: 0,
                event_masks: HashMap::new(),
                save_set: HashSet::new(),
                big_requests_enabled: false,
                xi2_masks: HashMap::new(),
                outbound: VecDeque::new(),
                watching_writable: false,
                focused_window: ROOT_WINDOW,
                reader_control: None,
            },
        );
        b
    }

    #[test]
    fn no_operation_returns_handled() {
        let mut state = ServerState::new();
        let mut backend = RecordingBackend::new();
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(7),
            RequestHeader {
                opcode: 127,
                data: 0,
                length_units: 1,
            },
            &[],
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
    }

    #[test]
    fn get_input_focus_writes_reply_through_client_io() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(3),
            RequestHeader {
                opcode: 43,
                data: 0,
                length_units: 1,
            },
            &[],
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));

        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).unwrap();
        // Reply opcode is 1 (Reply), sequence in bytes 2..4 little-endian.
        assert_eq!(buf[0], 1);
        assert_eq!(u16::from_le_bytes([buf[2], buf[3]]), 3);
    }

    #[test]
    fn grab_server_is_log_only_no_op() {
        let mut state = ServerState::new();
        let mut backend = RecordingBackend::new();
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(2),
            RequestHeader {
                opcode: 36,
                data: 0,
                length_units: 1,
            },
            &[],
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
    }

    #[test]
    fn list_hosts_writes_reply() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(11),
            RequestHeader {
                opcode: 110,
                data: 0,
                length_units: 1,
            },
            &[],
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));

        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).unwrap();
        assert_eq!(buf[0], 1, "Reply opcode");
        assert_eq!(u16::from_le_bytes([buf[2], buf[3]]), 11);
    }

    #[test]
    fn dri3_hidden_when_caps_unsupported() {
        // Default RecordingBackend returns Dri3Caps::unsupported()
        // (version (0, 0)), so DRI3 must not appear in QueryExtension /
        // ListExtensions output. KmsBackend overrides
        // dri3_capabilities() and the Phase 4.2 vng smoke covers the
        // advertised path.
        let mut backend = RecordingBackend::new();
        assert!(extension_query_reply("DRI3", &mut backend).is_none());
        let names = advertised_extension_names(&mut backend);
        assert!(
            !names.contains(&"DRI3"),
            "DRI3 should be hidden when caps unsupported, got: {names:?}"
        );
    }

    #[test]
    fn sync_create_trigger_query_fence_round_trip() {
        let mut state = ServerState::new();
        let peer_a = install_client(&mut state, 1);
        let mut peer_b = install_client(&mut state, 2);
        let mut backend = RecordingBackend::new();

        // Client A: CreateFence(fence=0x42, initially_triggered=false).
        let mut create_body = vec![0u8; 12];
        create_body[0..4].copy_from_slice(&0u32.to_le_bytes()); // drawable=0
        create_body[4..8].copy_from_slice(&0x42u32.to_le_bytes());
        create_body[8] = 0;
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 142,
                data: 14, // CREATE_FENCE
                length_units: 4,
            },
            &create_body,
            None,
        )
        .unwrap();

        // Client B: QueryFence -> triggered=false initially.
        let mut q_body = vec![0u8; 4];
        q_body[0..4].copy_from_slice(&0x42u32.to_le_bytes());
        process_request(
            &mut state,
            &mut backend,
            ClientId(2),
            SequenceNumber(1),
            RequestHeader {
                opcode: 142,
                data: 18, // QUERY_FENCE
                length_units: 2,
            },
            &q_body,
            None,
        )
        .unwrap();
        peer_b.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer_b.read_exact(&mut buf).unwrap();
        assert_eq!(buf[0], 1); // Reply
        assert_eq!(buf[8], 0, "fence not yet triggered");

        // Client A: TriggerFence.
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(2),
            RequestHeader {
                opcode: 142,
                data: 15, // TRIGGER_FENCE
                length_units: 2,
            },
            &q_body,
            None,
        )
        .unwrap();

        // Client B: QueryFence -> triggered=true now.
        process_request(
            &mut state,
            &mut backend,
            ClientId(2),
            SequenceNumber(2),
            RequestHeader {
                opcode: 142,
                data: 18, // QUERY_FENCE
                length_units: 2,
            },
            &q_body,
            None,
        )
        .unwrap();
        let mut buf2 = [0u8; 32];
        peer_b.read_exact(&mut buf2).unwrap();
        assert_eq!(buf2[8], 1, "fence triggered after Client A's trigger");

        // Stash peer_a so it doesn't drop and close the writer mid-test.
        let _ = peer_a;
    }

    #[test]
    fn dri3_get_supported_modifiers_default_window_subset_screen() {
        // Default Backend::dri3_supported_modifiers returns
        // ([LINEAR], [LINEAR]); the window list must always be a
        // subset of the screen list per design §3.2.
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let mut body = vec![0u8; 8];
        body[0..4].copy_from_slice(&0xCAFEu32.to_le_bytes()); // window
        body[4] = 24;
        body[5] = 32;
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(11),
            RequestHeader {
                opcode: 147,
                data: 6, // GET_SUPPORTED_MODIFIERS
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
        peer.set_nonblocking(true).unwrap();
        // Reply: 32-byte header + 8*nwin + 8*nscr; nwin=nscr=1.
        let mut buf = [0u8; 48];
        peer.read_exact(&mut buf).expect("reply bytes delivered");
        assert_eq!(buf[0], 1, "expected Reply, got opcode {}", buf[0]);
        let nwin = u32::from_le_bytes(buf[8..12].try_into().unwrap());
        let nscr = u32::from_le_bytes(buf[12..16].try_into().unwrap());
        assert!(nwin <= nscr, "window-list must be subset: {nwin} > {nscr}");
        assert_eq!(nwin, 1);
        assert_eq!(nscr, 1);
        let m_win = u64::from_le_bytes(buf[32..40].try_into().unwrap());
        let m_scr = u64::from_le_bytes(buf[40..48].try_into().unwrap());
        assert_eq!(m_win, 0); // LINEAR
        assert_eq!(m_scr, 0);
    }

    #[test]
    fn dri3_pixmap_from_buffers_rejects_multi_plane() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // 60-byte body with num_buffers=2 (multi-plane). Phase 4.2
        // accepts only num_buffers==1; everything else returns
        // BadAlloc per design "single-plane RGB only" scope.
        let mut body = vec![0u8; 60];
        body[0..4].copy_from_slice(&0xAAAA_AAAAu32.to_le_bytes()); // pixmap xid
        body[4..8].copy_from_slice(&0xBBBB_BBBBu32.to_le_bytes()); // window xid
        body[8] = 2; // num_buffers
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(5),
            RequestHeader {
                opcode: 147,
                data: 7, // PIXMAP_FROM_BUFFERS
                length_units: 16,
            },
            &body,
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).expect("error bytes delivered");
        assert_eq!(buf[0], 0, "expected Error, got opcode {}", buf[0]);
        assert_eq!(buf[1], 11, "expected BadAlloc (11), got {}", buf[1]);
    }

    #[test]
    fn dri3_open_emits_bad_alloc_when_backend_unsupported() {
        // RecordingBackend's default Backend::dri3_open returns Err
        // (DRI3 unsupported). The dispatcher must convert that to a
        // BadAlloc error event, not a successful reply.
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let mut body = vec![0u8; 8];
        body[0..4].copy_from_slice(&0xCAFEu32.to_le_bytes()); // drawable
        body[4..8].copy_from_slice(&0u32.to_le_bytes()); // provider
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(3),
            RequestHeader {
                opcode: 147,
                data: 1, // OPEN
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
        // Read 32 bytes from the peer end of the client's UnixStream:
        // X errors are 32-byte fixed-size messages with opcode 0 in
        // byte 0 and the error code in byte 1.
        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf)
            .expect("error bytes delivered to peer");
        assert_eq!(buf[0], 0, "expected Error (opcode 0), got {}", buf[0]);
        assert_eq!(buf[1], 11, "expected BadAlloc (11), got {}", buf[1]);
    }

    #[test]
    fn unsupported_opcode_returns_handled() {
        let mut state = ServerState::new();
        let mut backend = RecordingBackend::new();
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 39, // GetMotionEvents — never implemented; default
                // arm logs and returns Handled.
                data: 0,
                length_units: 4,
            },
            &[],
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
    }

    // ---- L2 plan B.1: COMPOSITE redirect dispatch policy --------

    fn composite_redirect_request_body(window: u32, mode: u8) -> Vec<u8> {
        let mut body = vec![0u8; 8];
        body[0..4].copy_from_slice(&window.to_le_bytes());
        body[4] = mode;
        body
    }

    fn dispatch_composite_redirect(
        state: &mut ServerState,
        backend: &mut dyn crate::backend::Backend,
        client_id: ClientId,
        window: u32,
        mode: u8,
    ) -> RequestOutcome {
        let body = composite_redirect_request_body(window, mode);
        process_request(
            state,
            backend,
            client_id,
            SequenceNumber(1),
            RequestHeader {
                opcode: 144,
                data: 1, // REDIRECT_WINDOW
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap()
    }

    #[test]
    fn redirect_window_conflict_from_different_client_returns_bad_access() {
        let mut state = ServerState::new();
        let _peer_a = install_client(&mut state, 1);
        let mut peer_b = install_client(&mut state, 2);
        let mut backend = RecordingBackend::new();
        // Client A redirects window 0xCAFE first (succeeds).
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0xCAFE, 0);
        // Client B tries the same redirect — must get BadAccess.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(2), 0xCAFE, 0);
        peer_b.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer_b.read_exact(&mut buf).expect("error delivered to B");
        assert_eq!(buf[0], 0, "expected X11 Error, got opcode {}", buf[0]);
        // BAD_ACCESS = 10
        assert_eq!(buf[1], 10, "expected BadAccess (10), got {}", buf[1]);
    }

    #[test]
    fn redirect_window_same_client_idempotent() {
        let mut state = ServerState::new();
        let mut peer_a = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // Two REDIRECT_WINDOW from the same client on the same window:
        // both should succeed with no error event written.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0xBEEF, 0);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0xBEEF, 0);
        peer_a.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        let n = peer_a.read(&mut buf).unwrap_or(0);
        assert_eq!(n, 0, "no error bytes expected, got {n} bytes: {buf:02x?}");
        assert_eq!(state.composite_redirects.len(), 1);
    }

    #[test]
    fn redirect_manual_mode_is_accepted() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // compositeproto: update=1 → Manual. xfwm4, picom, xcompmgr,
        // and mate-panel's notification-area-applet all request Manual.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0xDEAD, 1);
        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        let n = peer.read(&mut buf).unwrap_or(0);
        assert_eq!(n, 0, "no error bytes expected, got {n} bytes: {buf:02x?}");
        assert_eq!(state.composite_redirects.len(), 1);
    }

    // ---------------- extract_shm_zpixmap_region ----------------
    //
    // The protocol-level byte-extraction for MIT-SHM PutImage. Until
    // 2026-05-15 the handler ignored `total_width` / `src_x` /
    // `src_y` and read a tightly-packed `src_width × src_height ×
    // bpp` block at `offset`. That happens to be correct when the
    // client sets `total == src` and `src_xy == 0` (the common
    // case), but reads garbage when the client uploads a sub-region
    // of a larger shm image. xfdesktop's thumbnail upload pattern
    // and any cairo-padded surface trigger the latter, which
    // manifests as horizontal-band corruption around the thumbnail.

    fn d32_pixel(b: u8, g: u8, r: u8, a: u8) -> [u8; 4] {
        // Wire byte order for a depth-32 ZPixmap is [B, G, R, A] —
        // see the comment in `try_vk_put_image`.
        [b, g, r, a]
    }

    #[test]
    fn extract_d32_tight_packing_returns_input() {
        // total == src, src_xy == 0 → output is exactly the input.
        let mut bytes = Vec::new();
        for y in 0..4u8 {
            for x in 0..4u8 {
                bytes.extend_from_slice(&d32_pixel(x, y, x ^ y, 0xFF));
            }
        }
        let out = extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 32)
            .expect("tight extraction succeeds");
        assert_eq!(out, bytes);
    }

    #[test]
    fn extract_d32_subregion_of_larger_buffer() {
        // 8×8 total, take 4×4 at (2, 2). The handler must read row 2
        // bytes 8..24, row 3 bytes 8..24, etc. — NOT 64 contiguous
        // bytes from offset 0, which is what the pre-fix handler
        // did.
        let mut bytes = Vec::new();
        for y in 0..8u8 {
            for x in 0..8u8 {
                bytes.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
            }
        }
        let out = extract_shm_zpixmap_region(&bytes, 0, 8, 8, 2, 2, 4, 4, 32)
            .expect("subregion extraction succeeds");
        // Output must be the (2,2)..(6,6) tile, tightly packed.
        let mut want = Vec::new();
        for y in 2..6u8 {
            for x in 2..6u8 {
                want.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
            }
        }
        assert_eq!(out, want);
    }

    #[test]
    fn extract_d32_total_wider_than_src() {
        // 16×4 total, take 4×4 at (0, 0). Each src row must skip the
        // unused 12 trailing pixels of the total row.
        let mut bytes = Vec::new();
        for y in 0..4u8 {
            for x in 0..16u8 {
                bytes.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
            }
        }
        let out = extract_shm_zpixmap_region(&bytes, 0, 16, 4, 0, 0, 4, 4, 32)
            .expect("wide-total extraction succeeds");
        let mut want = Vec::new();
        for y in 0..4u8 {
            for x in 0..4u8 {
                want.extend_from_slice(&d32_pixel(x, y, 0, 0xFF));
            }
        }
        assert_eq!(out, want);
    }

    #[test]
    fn extract_honors_offset() {
        // Image starts partway into the shm segment.
        let mut bytes = vec![0xAAu8; 16];
        for y in 0..2u8 {
            for x in 0..2u8 {
                bytes.extend_from_slice(&d32_pixel(x, y, 0xFF, 0xFF));
            }
        }
        let out = extract_shm_zpixmap_region(&bytes, 16, 2, 2, 0, 0, 2, 2, 32)
            .expect("offset extraction succeeds");
        assert_eq!(out, &bytes[16..]);
    }

    #[test]
    fn extract_d8_padding_total_wider_than_src() {
        // 6-wide total → 8 bytes/row (padded to 32-bit). Take a 5×2
        // tile. Output stride is `((5 + 3) & ~3) = 8` bytes/row so
        // we get 16 bytes; first 5 are image data, next 3 are pad.
        let bytes: Vec<u8> = (0..16).map(|i| i as u8).collect();
        let out = extract_shm_zpixmap_region(&bytes, 0, 6, 2, 0, 0, 5, 2, 8)
            .expect("d8 extraction succeeds");
        assert_eq!(out.len(), 16);
        // Row 0 image bytes: 0..5 of the input; row 0 trailing pad: zero.
        assert_eq!(&out[..5], &bytes[..5]);
        assert_eq!(&out[5..8], &[0, 0, 0]);
        // Row 1 image bytes: 8..13 of the input.
        assert_eq!(&out[8..13], &bytes[8..13]);
        assert_eq!(&out[13..16], &[0, 0, 0]);
    }

    #[test]
    fn extract_d8_src_x_offset() {
        // 8-wide total → 8 bytes/row. Take a 4×1 tile at src_x=2.
        let bytes: Vec<u8> = (0..8).map(|i| i as u8).collect();
        let out = extract_shm_zpixmap_region(&bytes, 0, 8, 1, 2, 0, 4, 1, 8)
            .expect("d8 src_x extraction succeeds");
        // src_width=4 → src_stride=4 (already 32-bit aligned). Output is bytes 2..6.
        assert_eq!(out, vec![2u8, 3, 4, 5]);
    }

    #[test]
    fn extract_rejects_region_outside_total() {
        let bytes = vec![0u8; 64];
        // src_x + src_width > total_width
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 2, 0, 4, 4, 32).is_none());
        // src_y + src_height > total_height
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 2, 4, 4, 32).is_none());
    }

    #[test]
    fn extract_rejects_negative_src_xy() {
        let bytes = vec![0u8; 64];
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, -1, 0, 4, 4, 32).is_none());
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, -1, 4, 4, 32).is_none());
    }

    #[test]
    fn extract_rejects_offset_beyond_buffer() {
        let bytes = vec![0u8; 16];
        // 4×4 d32 = 64 bytes; only 16 available.
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 32).is_none());
    }

    #[test]
    fn extract_rejects_unsupported_depth() {
        let bytes = vec![0u8; 64];
        assert!(extract_shm_zpixmap_region(&bytes, 0, 4, 4, 0, 0, 4, 4, 16).is_none());
    }

    #[test]
    fn extract_d24_treats_padding_byte_as_image_data() {
        // d24 on the wire is 4 bytes per pixel like d32; the 4th
        // byte is undefined but transmitted. Extraction must copy
        // all 4 bytes — the put_image backend stamps 0xFF later.
        let mut bytes = Vec::new();
        for y in 0..2u8 {
            for x in 0..2u8 {
                bytes.extend_from_slice(&d32_pixel(x, y, 0xCC, 0x77));
            }
        }
        let out = extract_shm_zpixmap_region(&bytes, 0, 2, 2, 0, 0, 2, 2, 24)
            .expect("d24 extraction succeeds");
        assert_eq!(out, bytes);
    }

    // ---------------- end extract_shm_zpixmap_region ----------------

    #[test]
    fn redirect_invalid_mode_returns_bad_value() {
        let mut state = ServerState::new();
        let mut peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // Anything outside {0, 1} is a spec violation → BadValue.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), 0xDEAD, 2);
        peer.set_nonblocking(true).unwrap();
        let mut buf = [0u8; 32];
        peer.read_exact(&mut buf).expect("error delivered");
        assert_eq!(buf[0], 0);
        // BAD_VALUE = 2
        assert_eq!(buf[1], 2, "expected BadValue (2), got {}", buf[1]);
        assert!(state.composite_redirects.is_empty());
    }

    // ---- T2: Manual-only activation + mode-transition gates --------

    fn install_window_with_host_xid(state: &mut ServerState, id: u32, host_xid: u32) {
        state.resources.create_window(
            ClientId(1),
            CreateWindowRequest {
                window: ResourceId(id),
                parent: ROOT_WINDOW,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                border_width: 0,
                depth: 32,
                visual: ResourceId(0),
                class: 0,
                background_pixel: None,
                bit_gravity: None,
                win_gravity: None,
                backing_store: None,
                backing_planes: None,
                backing_pixel: None,
                override_redirect: Some(true),
                save_under: None,
                event_mask: None,
                do_not_propagate_mask: None,
                colormap: None,
            },
        );
        let handle = crate::backend::WindowHandle::from_raw_panicking(host_xid);
        if let Some(w) = state.resources.window_mut(ResourceId(id)) {
            w.host_xid = Some(handle);
        }
    }

    #[test]
    fn redirect_window_manual_activates_backing_and_skip_scanout() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let win_xid = 0x0100_0001;
        let host_xid = 0x0200_0001;
        install_window_with_host_xid(&mut state, win_xid, host_xid);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 1);
        // Backend allocated a backing AND was told to skip the window
        // in scanout.
        let calls = backend.calls();
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::AllocateRedirectedBacking { host_window, .. }
                    if *host_window == host_xid
            )),
            "expected AllocateRedirectedBacking, got: {calls:?}",
        );
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::SetWindowScanoutSkipped { host_window, skip: true }
                    if *host_window == host_xid
            )),
            "expected SetWindowScanoutSkipped(true), got: {calls:?}",
        );
        // State-side: redirected_backing populated.
        assert!(
            state
                .resources
                .window(ResourceId(win_xid))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_some(),
            "redirected_backing should be populated for Manual",
        );
    }

    #[test]
    fn redirect_window_automatic_does_not_activate_backing() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let win_xid = 0x0100_0002;
        let host_xid = 0x0200_0002;
        install_window_with_host_xid(&mut state, win_xid, host_xid);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 0);
        // Regression guard for 92a2a83 (broke MATE by activating
        // backings in Automatic mode too).
        let calls = backend.calls();
        assert!(
            !calls
                .iter()
                .any(|c| matches!(c, RecordedCall::AllocateRedirectedBacking { .. })),
            "Automatic mode must not allocate a backing, got: {calls:?}",
        );
        assert!(
            !calls
                .iter()
                .any(|c| matches!(c, RecordedCall::SetWindowScanoutSkipped { .. })),
            "Automatic mode must not toggle scanout-skip, got: {calls:?}",
        );
        assert!(
            state
                .resources
                .window(ResourceId(win_xid))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_none(),
            "Automatic mode must leave redirected_backing as None",
        );
    }

    #[test]
    fn redirect_subwindows_manual_walks_children() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // Two top-level children of root, each with a host xid.
        install_window_with_host_xid(&mut state, 0x0100_0010, 0x0200_0010);
        install_window_with_host_xid(&mut state, 0x0100_0011, 0x0200_0011);
        // RedirectSubwindows(root, Manual) — root is ROOT_WINDOW (xid 1).
        let body = composite_redirect_request_body(ROOT_WINDOW.0, 1);
        let outcome = process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 144,
                data: 2, // REDIRECT_SUBWINDOWS
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        assert!(matches!(outcome, RequestOutcome::Handled));
        let calls = backend.calls();
        let allocs: Vec<u32> = calls
            .iter()
            .filter_map(|c| match c {
                RecordedCall::AllocateRedirectedBacking { host_window, .. } => Some(*host_window),
                _ => None,
            })
            .collect();
        assert!(allocs.contains(&0x0200_0010), "child 1 backing missing");
        assert!(allocs.contains(&0x0200_0011), "child 2 backing missing");
    }

    #[test]
    fn mode_transition_manual_to_automatic_tears_backing() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let win_xid = 0x0100_0020;
        let host_xid = 0x0200_0020;
        install_window_with_host_xid(&mut state, win_xid, host_xid);
        // First Manual → backing activated.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 1);
        // Same owner re-redirects as Automatic — must tear backing
        // down and clear scanout-skip.
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 0);
        let calls = backend.calls();
        assert!(
            calls
                .iter()
                .any(|c| matches!(c, RecordedCall::ReleaseRedirectedBacking(_))),
            "Manual → Automatic must release backing, got: {calls:?}",
        );
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::SetWindowScanoutSkipped { host_window, skip: false }
                    if *host_window == host_xid
            )),
            "Manual → Automatic must clear scanout-skip, got: {calls:?}",
        );
        assert!(
            state
                .resources
                .window(ResourceId(win_xid))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_none(),
            "redirected_backing must be cleared after Manual→Automatic",
        );
    }

    #[test]
    fn mode_transition_automatic_to_manual_activates_backing() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let win_xid = 0x0100_0030;
        let host_xid = 0x0200_0030;
        install_window_with_host_xid(&mut state, win_xid, host_xid);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 0);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 1);
        let calls = backend.calls();
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::AllocateRedirectedBacking { host_window, .. }
                    if *host_window == host_xid
            )),
            "Automatic → Manual must activate backing, got: {calls:?}",
        );
        assert!(
            state
                .resources
                .window(ResourceId(win_xid))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_some(),
            "redirected_backing must be populated after Automatic→Manual",
        );
    }

    #[test]
    fn resize_redirected_manual_window_rotates_backing_without_clearing_skip() {
        // The resize rotation releases the OLD backing and allocates a
        // NEW one in its place, while the window stays redirected the
        // whole time. The plan's load-bearing invariant: the scanout-
        // skip flag must NOT be toggled by the rotation — it lives on
        // the backend's `windows_redirected_manual` set, toggled only
        // at activate / teardown / mode-transition boundaries.
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        let win_xid = 0x0100_0040;
        let host_xid = 0x0200_0040;
        install_window_with_host_xid(&mut state, win_xid, host_xid);
        dispatch_composite_redirect(&mut state, &mut backend, ClientId(1), win_xid, 1);
        // Reset the call log: anything before the rotation is
        // already-tested noise.
        backend.calls.lock().unwrap().clear();
        // Simulate the resize path.
        rotate_redirected_backing_on_resize(
            &mut state,
            &mut backend,
            None,
            ResourceId(win_xid),
            200,
            150,
        );
        let calls = backend.calls();
        // Allocation of the new backing happened…
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::AllocateRedirectedBacking { host_window, width, height, .. }
                    if *host_window == host_xid && *width == 200 && *height == 150
            )),
            "resize must allocate a new backing at new dimensions, got: {calls:?}",
        );
        // …old backing released…
        assert!(
            calls
                .iter()
                .any(|c| matches!(c, RecordedCall::ReleaseRedirectedBacking(_))),
            "resize must release the old backing, got: {calls:?}",
        );
        // …but scanout-skip MUST stay set: no false-toggle was emitted.
        assert!(
            !calls
                .iter()
                .any(|c| matches!(c, RecordedCall::SetWindowScanoutSkipped { skip: false, .. })),
            "resize must not clear scanout-skip while window stays redirected, got: {calls:?}",
        );
        // State-side: the backing now reflects the new geometry.
        let backing = state
            .resources
            .window(ResourceId(win_xid))
            .and_then(|w| w.redirected_backing.as_ref())
            .copied()
            .expect("redirected_backing populated after rotation");
        assert_eq!(backing.width, 200);
        assert_eq!(backing.height, 150);
    }

    #[test]
    fn unredirect_subwindows_tears_down_all_children() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        install_window_with_host_xid(&mut state, 0x0100_0070, 0x0200_0070);
        install_window_with_host_xid(&mut state, 0x0100_0071, 0x0200_0071);
        // Activate Manual subwindows redirect on root.
        let body = composite_redirect_request_body(ROOT_WINDOW.0, 1);
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 144,
                data: 2, // REDIRECT_SUBWINDOWS
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        // Confirm preconditions: both children carry a backing now.
        assert!(
            state
                .resources
                .window(ResourceId(0x0100_0070))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_some()
        );
        assert!(
            state
                .resources
                .window(ResourceId(0x0100_0071))
                .and_then(|w| w.redirected_backing.as_ref())
                .is_some()
        );
        // UnredirectSubwindows on root.
        let body = composite_redirect_request_body(ROOT_WINDOW.0, 0);
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(2),
            RequestHeader {
                opcode: 144,
                data: 4, // UNREDIRECT_SUBWINDOWS
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        // Both children torn down: redirected_backing cleared, the
        // backend received per-child SetWindowScanoutSkipped(false).
        for child in [0x0100_0070u32, 0x0100_0071] {
            assert!(
                state
                    .resources
                    .window(ResourceId(child))
                    .and_then(|w| w.redirected_backing.as_ref())
                    .is_none(),
                "redirected_backing must be cleared for child 0x{child:x}",
            );
        }
        let calls = backend.calls();
        let clears: Vec<u32> = calls
            .iter()
            .filter_map(|c| match c {
                RecordedCall::SetWindowScanoutSkipped {
                    host_window,
                    skip: false,
                } => Some(*host_window),
                _ => None,
            })
            .collect();
        assert!(clears.contains(&0x0200_0070), "child 1 not cleared");
        assert!(clears.contains(&0x0200_0071), "child 2 not cleared");
    }

    #[test]
    fn create_window_under_manual_subwindows_inherits_backing() {
        let mut state = ServerState::new();
        let _peer = install_client(&mut state, 1);
        let mut backend = RecordingBackend::new();
        // RedirectSubwindows(root, Manual). No children yet.
        let body = composite_redirect_request_body(ROOT_WINDOW.0, 1);
        process_request(
            &mut state,
            &mut backend,
            ClientId(1),
            SequenceNumber(1),
            RequestHeader {
                opcode: 144,
                data: 2,
                length_units: 3,
            },
            &body,
            None,
        )
        .unwrap();
        backend.calls.lock().unwrap().clear();
        // A new direct child of root should pick up a backing.
        install_window_with_host_xid(&mut state, 0x0100_0050, 0x0200_0050);
        // CreateWindow handler activates via parent_has_manual_subwindows_redirect.
        // The helper directly calls activate_redirect_backing_for in
        // production via the CreateWindow request path; for this unit
        // test we invoke the same helper to keep the assertion focused.
        let parent = state
            .resources
            .window(ResourceId(0x0100_0050))
            .map(|w| w.parent)
            .unwrap();
        assert!(parent_has_manual_subwindows_redirect(&state, parent));
        activate_redirect_backing_for(&mut state, &mut backend, None, ResourceId(0x0100_0050));
        let calls = backend.calls();
        assert!(
            calls.iter().any(|c| matches!(
                c,
                RecordedCall::AllocateRedirectedBacking { host_window, .. }
                    if *host_window == 0x0200_0050
            )),
            "new child under Manual-subwindows redirect must get a backing, got: {calls:?}",
        );
    }
}
